function splitWord(w,snd){var dig=['ai','oa','ie','ee','or'],r=[],i=0;while(i<w.length){var two=w.substr(i,2);if(dig.indexOf(two)>=0){r.push(two);i+=2}else{r.push(w[i]);i++}}return r}
