VIEWS.parent=function(tab){if(!PIN_OK){var s='';function d(){app.innerHTML=top('وضع الوالدين 🔒','أدخل الرقم السري',true)+'<div class="pin">'+[0,1,2,3].map(function(k){return '<i class="'+(k<s.length?'on':'')+'"></i>'}).join('')+'</div><div class="pad">'+[1,2,3,4,5,6,7,8,9,'',0,'⌫'].map(function(k){return k===''?'<span></span>':'<button data-k="'+k+'">'+k+'</button>'}).join('')+'</div><button class="big ghost" id="fpin" style="font-size:1rem;min-height:52px">🤔 نسيت الرقم السري؟</button>';
  document.getElementById('fpin').onclick=function(){var a=6+Math.floor(Math.random()*4),b=6+Math.floor(Math.random()*4),r=prompt('للكبار فقط: كم حاصل '+a+' × '+b+'؟');if(r==null)return;if(+r===a*b){alert('الرقم السري: '+S.pin+'\nتقدر تغيّره من الإعدادات.');PIN_OK=true;VIEWS.parent(tab)}else toast('الإجابة غير صحيحة')};
  app.querySelectorAll('[data-k]').forEach(function(b){b.onclick=function(){var k=b.dataset.k;if(k==='⌫')s=s.slice(0,-1);else if(s.length<4)s+=k;sfx('tap');if(s.length===4){if(s===S.pin){PIN_OK=true;VIEWS.parent(tab);return}toast('رقم غلط');s=''}d()}})}d();return}
 tab=tab||'set';var T=[['set','⚙️ الإعدادات'],['week','📅 الأسبوع'],['log','🎤 التسميع'],['pace','📈 التنبيهات'],['level','🧭 المستوى'],['voice','🎙️ أصواتي'],['backup','💾 النسخ']];
 var h=top('وضع الوالدين 👪','',true)+'<div class="ptabs">'+T.map(function(x){return '<button class="'+(x[0]===tab?'on':'')+'" data-t="'+x[0]+'">'+x[1]+'</button>'}).join('')+'</div>';
 app.innerHTML=h+'<div id="pb"></div>';app.querySelectorAll('[data-t]').forEach(function(b){b.onclick=function(){VIEWS.parent(b.dataset.t)}});
 var pb=document.getElementById('pb');PT[tab](pb);V={view:'parent',arg:tab}};
var PT={};
PT.set=function(pb){fixCur();pb.innerHTML='<div class="card pf"><label>اسم الطالبة<input id="sn" value="'+esc(S.name)+'" maxlength="20"></label><label>المقدار اليومي<select id="sa">'+[1,2,3].map(function(n){return '<option value="'+n+'"'+(S.amount===n?' selected':'')+'>'+n+' '+(n===1?'آية':n===2?'آيتان':'آيات')+'</option>'}).join('')+'</select></label>'+
 '<label>السورة الحالية<select id="ss">'+QURAN.map(function(q,i){return '<option value="'+i+'"'+(S.cur.i===i?' selected':'')+'>'+q.name+(S.done.indexOf(i)>=0?' ✔️':'')+(S.school.indexOf(i)>=0?' 🏫':'')+'</option>'}).join('')+'</select></label><label>تبدأ من الآية<input id="sy" type="number" min="1" value="'+((S.cur.a||0)+1)+'"></label>'+
 '<button class="big ghost" id="sk">🏫 تحفظها من المدرسة (تجاوز السورة الحالية بعد تسميعها)</button><label class="mt">مكافأة الخميس (تظهر لما تفتح الصندوق)<input id="sr" value="'+esc(S.reward)+'" placeholder="مثال: نطلع الحديقة 🌳"></label><label>الشكل<select id="th"><option value=""'+(!S.theme?' selected':'')+'>تلقائي</option><option value="light"'+(S.theme==='light'?' selected':'')+'>فاتح</option><option value="dark"'+(S.theme==='dark'?' selected':'')+'>ليلي</option></select></label><label>كلمة الإنجليزي: الأسبوع<select id="ew"><option value="">تلقائي</option>'+EN_WEEKS.map(function(w,k){return '<option value="'+k+'"'+(S.en.week===k?' selected':'')+'>'+(k+1)+': '+w.snd.join(' ')+'</option>'}).join('')+'</select></label><label>تغيير الرقم السري<input id="sp" inputmode="numeric" maxlength="4" placeholder="اتركه فاضي إذا ما تبي تغيّره"></label><button class="big" id="sv">💾 حفظ</button></div>';
 document.getElementById('sk').onclick=function(){var i=S.cur.i;if(i>=QURAN.length)return;if(S.school.indexOf(i)<0)S.school.push(i);QURAN[i].a.forEach(function(_,a){if(!S.mem[key(i,a)])S.mem[key(i,a)]=addDays(today(),-30)});logIt({t:'school',i:i});S.cur={i:i+1,a:0};fixCur();save();toast('تمام، تجاوزنا سورة '+QURAN[i].name);PT.set(pb)};
 document.getElementById('sv').onclick=function(){S.name=document.getElementById('sn').value.trim();S.amount=+document.getElementById('sa').value;var ni=+document.getElementById('ss').value,na=Math.max(0,Math.min(QURAN[ni].a.length-1,(+document.getElementById('sy').value||1)-1));if(ni!==S.cur.i||na!==S.cur.a){S.cur={i:ni,a:na};S.done=S.done.filter(function(x){return x!==ni});S.school=S.school.filter(function(x){return x!==ni})}
  S.reward=document.getElementById('sr').value.trim();S.theme=document.getElementById('th').value;if(S.theme)document.documentElement.setAttribute('data-theme',S.theme);else document.documentElement.removeAttribute('data-theme');var ew=document.getElementById('ew').value;S.en.week=ew===''?null:+ew;var p=document.getElementById('sp').value.trim();if(p){if(/^\d{4}$/.test(p))S.pin=p;else{toast('الرقم السري 4 أرقام');return}}save();toast('انحفظ ✅')}};
PT.week=function(pb){var t=today(),ws=weekStart(t),rows='';for(var k=0;k<7;k++){var d=addDays(ws,k),L=S.log.filter(function(x){return x.d===d}),nw=L.filter(function(x){return x.t==='new'&&x.ok}),nr=L.filter(function(x){return x.t==='near'}),ne=nr.filter(function(x){return !x.ok}).length,th=L.filter(function(x){return x.t==='thu'}),day=S.days[d];
 rows+='<tr><th>'+DAYS[k]+'<br><small class="muted">'+d.slice(5)+'</small></th><td>'+(day&&day.done?'⭐':'')+(dayType(d)==='rest'?'🌙':'')+'</td><td>'+(nw.length?nw.map(function(x){return QURAN[x.i].name+' '+(x.a+1)}).join('، '):'—')+'</td><td>'+(nr.length?(nr.length-ne)+'/'+nr.length:'—')+(th.length?'<br>تسميع: '+th.filter(function(x){return x.ok}).length+'/'+th.length:'')+'</td><td><input data-n="'+d+'" value="'+esc(S.notes[d]||'')+'" placeholder="ملاحظة" style="width:100%;font:inherit;padding:6px;border-radius:10px;border:1px solid var(--line);background:var(--bg);color:var(--ink)"></td></tr>'}
 var w=EN_WEEKS[enWeek(t)];pb.innerHTML='<div class="card" style="overflow-x:auto"><p style="margin-top:0"><b>أسبوع '+ws+'</b> · أصوات الإنجليزي: <span class="en">'+w.snd.join(' ')+'</span> · كلمات: <span class="en">'+topicOf(t).name+'</span> · كلمة الأسبوع: <b class="en">'+sightOf(t)+'</b></p><table class="wk"><tr><th>اليوم</th><th></th><th>الجديد</th><th>القريب</th><th>ملاحظات</th></tr>'+rows+'</table></div>';
 pb.querySelectorAll('[data-n]').forEach(function(i){i.onchange=function(){S.notes[i.dataset.n]=i.value;save()}})};
PT.log=function(pb){var L=S.log.slice(-60).reverse(),lab={new:'جديد',near:'قريب',far:'بعيد',thu:'تسميع الخميس',school:'من المدرسة',manual:'تسميع يدوي'};
 pb.innerHTML='<div class="card pf"><p style="margin-top:0"><b>سجّل تسميع يدوي</b></p><label>السورة<select id="ms">'+QURAN.map(function(q,i){return '<option value="'+i+'">'+q.name+'</option>'}).join('')+'</select></label><div class="row"><button class="big grow" id="mo">✔️ ممتاز</button><button class="big rose grow" id="mx">✖️ يحتاج مراجعة</button></div></div><div class="card"><table class="wk"><tr><th>التاريخ</th><th>النوع</th><th>الموضع</th><th></th></tr>'+(L.length?L.map(function(x){return '<tr><td>'+x.d.slice(5)+'</td><td>'+(lab[x.t]||x.t)+'</td><td>'+(x.i!=null?QURAN[x.i].name+(x.a!=null?' '+(x.a+1):''):'')+'</td><td>'+(x.ok===undefined?'':x.ok?'✔️':'✖️')+'</td></tr>'}).join(''):'<tr><td colspan="4" class="muted">لا يوجد تسميع بعد</td></tr>')+'</table></div>';
 function m(ok){logIt({t:'manual',i:+document.getElementById('ms').value,ok:ok});toast('انحفظ');PT.log(pb)}document.getElementById('mo').onclick=function(){m(true)};document.getElementById('mx').onclick=function(){m(false)}};
PT.pace=function(pb){var t=today(),from=addDays(t,-14),L=S.log.filter(function(x){return x.d>=from&&(x.t==='new'||x.t==='near'||x.t==='thu')}),ok=L.filter(function(x){return x.ok}).length,rate=L.length?ok/L.length:null,flags=Object.keys(S.flags).filter(function(d){return d>=from}).length,msg,cls='note';
 if(rate===null)msg='ما في بيانات كافية بعد. كمّلوا أسبوعين وراح يطلع لك اقتراح هني.';
 else if(rate>=.9&&!flags){msg='👍 الحفظ سهل عليها أسبوعين متتاليين ('+Math.round(rate*100)+'٪ صحيح). تقدر تزيد آية: المقدار الحالي '+S.amount+'.';}
 else if(rate<.7||flags>=2){cls='note warn';msg='🐢 فيه تعب أو نسيان ('+Math.round(rate*100)+'٪ صحيح، و'+flags+' مرات أخطاء في القريب). الأفضل تقلل الجديد وتزيد المراجعة.'}
 else msg='✅ المستوى مناسب ('+Math.round(rate*100)+'٪ صحيح). كمّلوا على نفس المقدار.';
 var tn=Object.keys(S.flags).filter(function(d){return d>=t}).map(function(d){return '<div class="note warn mt">⚠️ '+DAYS[dow(d)]+' '+d.slice(5)+': ما في جديد (أخطاء أكثر من موضعين في القريب)</div>'}).join('');
 pb.innerHTML='<div class="card"><div class="'+cls+'">'+msg+'</div>'+tn+'<div class="row mt"><button class="big ghost grow" id="pl">➖ قلّل آية</button><button class="big ghost grow" id="pp">➕ زِد آية</button></div></div>';
 document.getElementById('pl').onclick=function(){S.amount=Math.max(1,S.amount-1);save();toast('المقدار: '+S.amount)};document.getElementById('pp').onclick=function(){S.amount=Math.min(3,S.amount+1);save();toast('المقدار: '+S.amount)}};
PT.level=function(pb){pb.innerHTML='<div class="card"><p style="margin-top:0">تقدر تعيد «التعرّف على المستوى» في أي وقت: تعلّم على السور اللي تحفظها، والأصوات اللي تعرفها.</p><button class="big sun" id="lv">🧭 افتح صفحة المستوى</button></div>';document.getElementById('lv').onclick=function(){go('welcome','b')}};
PT.voice=function(pb){pb.innerHTML='<div class="card"><p style="margin-top:0"><b>سجّل صوتك لأصوات الحروف</b> 🎙️ — صوت ماما أو بابا أحلى من صوت الجهاز، والتطبيق يستخدم تسجيلك بدل النطق الآلي.</p><div class="wgrid g3" id="vg"></div></div>';
 var vg=document.getElementById('vg');SOUNDS.forEach(function(s){var b=document.createElement('div');b.className='wcard';b.innerHTML='<span style="font-size:2rem">'+s.k+'</span><span class="em" style="font-size:1.6rem">'+s.em+'</span><div class="row" style="gap:6px"><button class="ib" style="width:44px;height:44px;font-size:1.1rem" data-r aria-label="تسجيل">⏺️</button><button class="ib" style="width:44px;height:44px;font-size:1.1rem" data-p aria-label="تشغيل">▶️</button></div>';vg.appendChild(b);
  recGet('snd:'+s.k).then(function(x){if(x)b.style.background='var(--mint2)'});
  b.querySelector('[data-p]').onclick=function(){sayLetter(s.k)};
  b.querySelector('[data-r]').onclick=function(){var btn=this;if(!navigator.mediaDevices||!window.MediaRecorder){toast('الجهاز ما يدعم التسجيل');return}navigator.mediaDevices.getUserMedia({audio:true}).then(function(st){var mr=new MediaRecorder(st),ch=[];mr.ondataavailable=function(e){ch.push(e.data)};mr.onstop=function(){st.getTracks().forEach(function(t){t.stop()});var bl=new Blob(ch,{type:mr.mimeType||'audio/webm'});recPut('snd:'+s.k,bl).then(function(){b.style.background='var(--mint2)';btn.textContent='⏺️';toast('انحفظ صوت '+s.k)})};mr.start();btn.textContent='🔴';toast('سجّل الصوت… (ثانيتين)');setTimeout(function(){mr.stop()},1800)}).catch(function(){toast('ما في إذن للمايك')})}})};
PT.backup=function(pb){pb.innerHTML='<div class="card"><p style="margin-top:0">كل التقدّم محفوظ على هالجهاز بس. خذ نسخة احتياطية كل فترة.</p><button class="big sky" id="ex">📤 تصدير نسخة احتياطية</button><label class="big ghost" style="cursor:pointer">📥 استرجاع من ملف<input type="file" id="im" accept="application/json" style="display:none"></label><button class="big rose mt" id="rs">🗑️ مسح كل البيانات</button></div>';
 document.getElementById('ex').onclick=function(){var b=new Blob([JSON.stringify(S,null,1)],{type:'application/json'}),f=new File([b],'ياسمينة-نسخة-'+today()+'.json',{type:'application/json'});if(navigator.canShare&&navigator.canShare({files:[f]}))navigator.share({files:[f]}).catch(function(){});else{var a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=f.name;document.body.appendChild(a);a.click();a.remove()}};
 document.getElementById('im').onchange=function(e){var f=e.target.files[0];if(!f)return;f.text().then(function(t){var o=JSON.parse(t);if(!o||o.v!==1)throw 0;S=Object.assign(def(),o);save();toast('تم الاسترجاع ✅');go('home')}).catch(function(){toast('الملف غير صالح')})};
 document.getElementById('rs').onclick=function(){var c=prompt('اكتب «امسح» للتأكيد');if(c==='امسح'){localStorage.removeItem(KEY);S=def();PIN_OK=false;go('home')}}};
